<?php require __DIR__.'/app/bootstrap.php';
$slug=substr((string)($_GET['slug']??''),0,255);
$a=query_one(public_article_select()." WHERE ".published_where()." AND a.slug=?",[$slug]);
if(!$a){http_response_code(404);render_header('Inkuru ntibonetse');echo '<main class="container content-section"><h1>Inkuru ntibonetse</h1><p>Yaba yarakuwe ku rubuga cyangwa URL ikaba yanditse nabi.</p></main>';render_footer();exit;}
try{$ref=parse_url((string)($_SERVER['HTTP_REFERER']??''),PHP_URL_HOST);$ref=is_string($ref)?substr($ref,0,190):null;db()->prepare('INSERT INTO analytics_events(event_type,article_id,referrer_host,locale) VALUES (?,?,?,?)')->execute(['article_view',(int)$a['id'],$ref,substr((string)$a['language'],0,10)]);}catch(Throwable){/* Analytics must never block public journalism. */}
$related=query_all(public_article_select()." WHERE ".published_where()." AND a.category_id=? AND a.id<>? ORDER BY a.published_at DESC LIMIT 3",[$a['category_id'],$a['id']]);
$rootId=(int)($a['original_article_id']?:$a['id']);$translations=query_all("SELECT language,slug FROM articles WHERE status='published' AND (id=? OR original_article_id=?)",[$rootId,$rootId]);$alternates=[];foreach($translations as $translation)if(in_array($translation['language'],['rw','en','fr'],true))$alternates[$translation['language']]=absolute_url('article.php?slug='.rawurlencode($translation['slug']));if($alternates)$alternates['x-default']=$alternates['rw']??reset($alternates);
$image=media_url($a['cover_image']);$socialImage=$image?(str_starts_with($image,'http')?$image:absolute_url($image)):null;
render_header($a['title'],$a['summary'],$a['language'],$alternates,$socialImage,'article');
$schema=['@context'=>'https://schema.org','@type'=>'NewsArticle','headline'=>$a['title'],'description'=>$a['summary'],'inLanguage'=>$a['language'],'datePublished'=>date(DATE_ATOM,strtotime($a['published_at'])),'dateModified'=>date(DATE_ATOM,strtotime($a['updated_at'])),'author'=>['@type'=>'Person','name'=>$a['author_name'],'url'=>absolute_url('author.php?id='.$a['author_id'])],'publisher'=>['@type'=>'Organization','name'=>cfg('site_name'),'url'=>cfg('app_url')],'mainEntityOfPage'=>absolute_url('article.php?slug='.rawurlencode($a['slug'])),'isAccessibleForFree'=>!$a['is_premium']];
if($socialImage) $schema['image']=[$socialImage];
?><script type="application/ld+json"><?=json_encode($schema,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?></script>
<main id="main-content" class="container article-shell"><div class="breadcrumb"><a href="<?=e(path())?>">AHABANZA</a> <span>/</span> <a href="<?=e(path('category.php?slug='.$a['category_slug']))?>"><?=e(strtoupper($a['category_name']))?></a></div><header class="article-header"><span class="overline"><?=e(strtoupper(str_replace('_',' ',$a['type'])))?> / <?=e($a['category_name'])?></span><h1><?=e($a['title'])?></h1><?php if(!empty($a['subheadline'])):?><p class="article-subheadline"><?=e($a['subheadline'])?></p><?php endif;?><p class="article-deck"><?=e($a['summary'])?></p><?php if(!empty($a['key_points'])):?><div class="key-points"><b>IBY’INGENZI</b><ul><?php foreach(array_filter(preg_split('/\R/u',$a['key_points'])) as $point):?><li><?=e(trim($point))?></li><?php endforeach;?></ul></div><?php endif;?><div class="article-byline"><div class="author-icon"><?=e(mb_substr($a['author_name'],0,1))?></div><div><strong><a href="<?=e(path('author.php?id='.$a['author_id']))?>"><?=e($a['author_name'])?></a></strong><span>Yatangajwe: <?=e(display_date($a['published_at']))?> · Yavuguruwe: <?=e(display_date($a['updated_at']))?> · <?=estimate_readtime($a['body'])?> min read</span></div><div class="byline-share"><button type="button" data-copy-url>KOPIYA LINK ↗</button></div></div><?php if($a['is_demo']):?><p class="demo-warning"><b>URUGERO RWO KUGERAGEZA:</b> Iyi nyandiko ni demo. Ntabwo ari amakuru yemejwe, kandi ntigomba gutangazwa nk'inkuru nyayo.</p><?php endif;?></header>
<?php if($image):?><figure class="article-figure"><img src="<?=e($image)?>" alt="<?=e(($a['image_alt']??'') ?: ($a['image_caption'] ?: $a['title']))?>"><figcaption><?=e($a['image_caption'] ?: 'Ifoto y’icyitegererezo')?> <?=e($a['image_credit'] ? ' — '.$a['image_credit'] : '')?></figcaption></figure><?php endif;?>
<div class="article-content-grid"><aside class="article-rail"><span>INKURU / <?=e(str_pad((string)$a['id'],3,'0',STR_PAD_LEFT))?></span><div class="rail-line"></div><a href="<?=e(path('about.php#ethics'))?>">HOW WE REPORT ↗</a></aside><article class="article-prose"><?=implode('',array_map(fn($p)=>'<p>'.nl2br(e(trim($p))).'</p>',array_filter(preg_split('/\R\s*\R/u',trim($a['body'])))))?><?php if($a['video_url'] && preg_match('~^(https://www\.youtube\.com/watch\?v=|https://youtu\.be/)([A-Za-z0-9_-]{11})~',$a['video_url'],$m)):?><div class="video-frame"><iframe title="Video y'inkuru" loading="lazy" allowfullscreen referrerpolicy="strict-origin-when-cross-origin" src="https://www.youtube-nocookie.com/embed/<?=e($m[2])?>"></iframe></div><?php endif;?>
<?php if($a['public_sources']):?><div class="article-sources"><strong>Inkomoko zisangirwa n’abasomyi</strong><p><?=nl2br(e($a['public_sources']))?></p></div><?php endif;?>
<?php if($a['correction_note']):?><div class="correction"><strong>ICYAKOSOWE</strong><p><?=nl2br(e($a['correction_note']))?></p></div><?php endif;?>
<div class="end-mark">✳</div><p class="editorial-contact">Ubonye ikosa muri iyi nkuru? <a href="<?=e(path('contact.php'))?>">Menyesha ubwanditsi.</a></p></article><aside class="article-aside"><span class="mini-label">AFRIVOX NEWS / EDITORIAL</span><b>FACTS FIRST.</b><p>Inkuru yizewe igomba kugira amakuru ashobora kugenzurwa.</p></aside></div>
<?php if($related):?><section class="related-section"><div class="section-heading"><h2>Izindi nkuru <i>wasoma.</i></h2></div><div class="stories-grid"><?php foreach($related as $item) card($item);?></div></section><?php endif;?></main><?php render_footer(); ?>
